/**
 * The engine support matrix, rendered from the capability profiles.
 *
 * Lives in `src/core` rather than in a script because the same document is a product surface: the
 * compatibility tool will return this content to a host AI, and a report generated by a build step
 * that the runtime cannot call tends to disagree with the runtime. One renderer, two consumers.
 */

import { ALL_CAPABILITIES, CAPABILITY_PROFILES } from './browser-use-capabilities.js';
import { VERIFIED, effectiveAnswer } from './browser-use-verified.js';
import { currentOs } from './browser-use-runtime.js';
import { ADAPTERS } from './browser-use-adapters.js';
import { PRODUCTS } from './browser-use-detect.js';
import type { CapabilityStatus, OperatingSystem } from './browser-use-contract.js';

const STATUS_GLYPH: Record<CapabilityStatus, string> = {
  VERIFIED_NATIVE: 'Y*',
  VERIFIED_MANAGED: 'Y*',
  PARTIALLY_VERIFIED: 'p',
  DETECTED_NOT_TESTED: 'd',
  UNSUPPORTED: 'N',
  BLOCKED_BY_ENVIRONMENT: 'E',
  UNKNOWN: '?',
};

/** Protocol facts worth a sentence each — the refusals a reader will otherwise misread as TODOs. */
const NOTABLE: Array<[string, string, string]> = [
  [
    'firefox',
    'accessibilityTree',
    'WebDriver BiDi defines no accessibility module, and Firefox 129 removed CDP. No transport carries an AX tree to us.',
  ],
  [
    'firefox',
    'screenshotFullPage',
    'BiDi capture is viewport-only; full-page was still an open specification issue when the draft was read.',
  ],
  [
    'safari',
    'attachToRunning',
    'safaridriver is a W3C WebDriver server; it exposes no endpoint for a browser that is already open.',
  ],
  ['safari', 'accessibilityTree', 'W3C WebDriver defines no accessibility tree at all.'],
  [
    'chrome',
    'websockets',
    'This process cannot route WebSocket frames through its own SSRF check because the driver layer does not expose them. Reported as unsupported rather than silently unproxied.',
  ],
  [
    'arc',
    'launch',
    'Arc ships a Chromium core with no documented remote-debugging interface. `?`, not `p`: nobody has made it start.',
  ],
];

export function renderEngineSupportMatrix(hostOs: OperatingSystem = currentOs()): string {
  const products = Object.keys(CAPABILITY_PROFILES).sort();
  const adapterProducts = new Set(ADAPTERS.map((a) => a.product));
  const lines: string[] = [];

  lines.push('# Engine support matrix', '');
  lines.push('Generated by `npm run gen:browser-matrix` from `src/core/browser-use-capabilities.ts`.');
  lines.push('**Do not edit by hand** — a test compares this file against the generator output.', '');
  lines.push(
    'Legend: `Y*` verified on this machine · `p` partially verified (read from a specification or',
    'source, not run here) · `d` detected but untested · `N` unsupported by the protocol ·',
    '`E` blocked by this environment · `?` unknown, deliberately not guessed.',
    '',
  );
  lines.push(
    '`Y*` marks a row this host actually ran. Everything else is read from a specification or source',
    'and labelled as such — the difference is the point of the table. Each `Y*` below names the probe',
    'artifact that produced it; the run log is `docs/browser-use/BROWSER_COMPATIBILITY_RESULTS.md`.',
    '',
  );
  for (const f of VERIFIED) {
    lines.push(`- \`${f.product} · ${f.capability} · ${f.os}\` — ${f.browserVersion} → \`${f.evidence}\``);
  }
  lines.push('');

  lines.push(`## Products (${products.length})`, '');
  lines.push('| product | engine | protocols | adapter | detection candidates |');
  lines.push('| --- | --- | --- | --- | --- |');
  for (const product of products) {
    const profile = CAPABILITY_PROFILES[product];
    const spec = PRODUCTS.find((p) => p.product === product);
    const candidates = spec
      ? ['windows', 'macos', 'linux'].reduce((n, os) => n + (spec.paths[os as 'windows']?.length ?? 0), 0) +
        spec.pathNames.length
      : 0;
    lines.push(
      `| \`${product}\` | ${profile.engine} | ${profile.protocols.join(', ')} | ${adapterProducts.has(product) ? 'yes' : '**no**'} | ${candidates} |`,
    );
  }
  lines.push('');

  lines.push('## Capabilities', '');
  lines.push('| capability | ' + products.join(' | ') + ' |');
  lines.push('| --- |' + products.map(() => ' --- ').join('|') + '|');
  for (const capability of ALL_CAPABILITIES) {
    const cells = products.map((product) => {
      const base = CAPABILITY_PROFILES[product].answers.find((a) => a.capability === capability);
      if (!base) return '`?`';
      const answer = effectiveAnswer(product, capability, base, hostOs);
      return `\`${STATUS_GLYPH[answer.status]}\``;
    });
    lines.push(`| \`${capability}\` | ${cells.join(' | ')} |`);
  }
  lines.push('');

  lines.push(
    '## Why the refusals are what they are',
    '',
    'Each of these is a protocol fact, not a to-do item. A row that reads `N` here does not become',
    '`p` by writing more code — it needs a different browser or a different transport.',
    '',
  );
  for (const [product, capability, reason] of NOTABLE) {
    const answer = CAPABILITY_PROFILES[product].answers.find((a) => a.capability === capability);
    lines.push(
      `- **\`${product}\` · \`${capability}\`** — status \`${answer?.status}\` via ${answer?.via ?? 'n/a'}: ${reason}`,
    );
    lines.push(`  - recorded reason: *${answer?.reason}*`);
  }
  lines.push('');

  lines.push('## Counts', '', '| status | answers |', '| --- | ---: |');
  const counts = new Map<CapabilityStatus, number>();
  for (const product of products) {
    for (const base of CAPABILITY_PROFILES[product].answers) {
      // Count what the table actually shows, not what the profiles alone would say — otherwise the
      // totals contradict the grid two lines above them.
      const a = effectiveAnswer(product, base.capability, base, hostOs);
      counts.set(a.status, (counts.get(a.status) ?? 0) + 1);
    }
  }
  for (const status of Object.keys(STATUS_GLYPH) as CapabilityStatus[]) {
    lines.push(`| \`${status}\` | ${counts.get(status) ?? 0} |`);
  }
  lines.push('', `Total answers: ${products.length} products × ${ALL_CAPABILITIES.length} capabilities.`, '');
  return lines.join('\n');
}
